import {icon,formula} from './v15-ui.mjs';
import {moduleDirectory} from './v15-analysis.mjs';
export function renderGuide(){return `<div class="v15-pagehead"><div><h1>使用手册</h1><span>从添加持仓到看懂组合</span></div></div><div class="v15-guide-layout"><nav class="v15-guide-toc" aria-label="手册目录">${[['start','开始使用'],['modules','组合分析'],['events','事件与资料'],['ai','AI解读'],['save','整理资料']].map(([id,name])=>`<a href="#guide" data-act="guide-section" data-id="${id}">${name}</a>`).join('')}</nav><div><div class="v15-guide-journey">${[['plus','添加持仓','搜索基金并填写持有金额','start'],['layers','看组合结构','找到共同持股与配置特征','modules'],['file','阅读事件与资料','查看原文和基金资料','events'],['bookmark','保存研究','把收藏与解读放在一起','save']].map(([i,title,desc,id])=>`<a href="#guide" data-act="guide-section" data-id="${id}">${icon(i)}<strong>${title}</strong><small>${desc}</small></a>`).join('')}</div><section class="v15-guide-card" id="guide-start"><h2>添加持仓</h2><div class="v15-guide-start"><ol class="v15-guide-steps"><li><h3>搜索基金</h3><p>输入代码或名称，核对基金名称和份额类别。例如同一基金的A类与C类分别选择。</p></li><li><h3>填写持有金额</h3><p>输入当前持有金额，系统自动计算组合占比。点击首页基金卡片，可以修改金额或删除基金。</p></li><li><h3>从图谱认识组合</h3><p>点击基金，查看它连接的前十只股票；点击卡片右上角箭头，在右侧阅读详情和全部已收录持股。</p></li></ol><div class="v15-guide-example"><small>操作示例</small><label>搜索基金<span>基金代码或名称</span></label><label>持有金额<span>填写当前金额 · 元</span></label><button class="v15-primary" data-act="edit-holdings">去添加持仓 ${icon('arrow')}</button></div></div>${formula('基金资金占比=该基金当前持有金额÷全部基金持有金额之和。股票占组合比例=Σ(基金资金占比×股票占该基金净资产比例)。','金额如何变成组合占比')}</section><section class="v15-guide-card" id="guide-modules"><h2>如何阅读持仓分析</h2><p>先选择想了解的模块，再向下查看当前组合的数字。每个模块都可以展开公式，或交给AI解释。</p>${moduleDirectory('',true)}<details class="v15-formula"><summary>有效持股数：股票很多，为什么仍然集中？</summary><div class="v15-guide-formula"><code>N<sub>有效</sub> = 1 / Σp²</code><p>名义持股数按证券代码去重。有效持股数把每只股票的权重考虑进来，p是股票在已展开股票中的占比。权重越均匀，有效持股数越接近名义持股数；少数股票占比越大，有效持股数越小。</p></div></details>${formula('同一期股票重叠度=Σmin(股票占基金A净资产比例，股票占基金B净资产比例)。组合共同持有占比统计两只及以上基金共同持有的股票；重复路径占比在每只股票下扣除最大单基金路径，再汇总。','两只基金与整个组合如何比较？')}${formula('回撤=1−当前价值/此前最高价值。最大回撤是区间中最大的回落幅度；恢复天数从低点算到重新达到此前高点。区间收益使用通过日增长率、数据质量与口径检查的复权观察序列。','历史回撤和区间收益如何阅读？')}<p>每个数字旁的报告日或净值区间，说明它对应哪一段时间。基金持仓按报告日比较，历史风险按共同有效净值日期计算。</p></section><section class="v15-guide-card" id="guide-events"><h2>从事件回到原文</h2><div class="v15-two-columns"><div><h3>事件时间轴</h3><p>默认查看所持基金与持仓公司的相关事件。按基金或公司搜索，可以切换对象；“基金自身”和“持仓公司”可分别浏览。</p><p>每条事件标明关联对象。点击“正文”直接阅读，点击“原文”打开来源页面；勾选多条后，可以一起生成摘要。</p><a class="v15-text-link" href="#news">去事件时间轴 ${icon('arrow')}</a></div><div><h3>公共资料库与帖子</h3><p>资料库可以按对象查找基金基础信息、持仓、净值和报告。帖子与评论按对象及日期浏览，收藏时选择分类。</p><a class="v15-text-link" href="#sources">去公共资料库 ${icon('arrow')}</a></div></div></section><section class="v15-guide-card" id="guide-ai"><h2>让AI解释你正在看的内容</h2><ol class="v15-guide-steps"><li><h3>选一个问题</h3><p>事件可以选择“整体与逐条摘要”“与持仓的关联”“要点与分歧”。持仓分析可以选择当前模块、整体组合、费用或历史体验。</p></li><li><h3>也可以自己提问</h3><p>例如：“这几条新闻主要发生了什么？分别涉及哪只基金的哪些持仓公司？”或“用简单的话解释有效持股数和名义持股数的差别。”</p></li><li><h3>继续浏览，等待结果</h3><p>分析进度显示在原页面，期间可以继续浏览。完成后会出现消息提醒，原页面的“最近一次分析”可以查看结果、写笔记和选择收藏分类。所有结果自动保存到“我的资料库”，点击顶部“AI分析”即可找到。结果中的来源按钮可以回到分析依据。</p></li></ol><details class="v15-formula"><summary>选择默认AI或自己的模型</summary><p>打开“设置”，选择默认AI即可使用站点配置的服务；也可以选择自己的接口并填写地址、API Key和模型名。两种方式都使用页面提供的固定提示词与当前选择的材料。</p><a class="v15-text-link" href="#settings">打开设置 ${icon('arrow')}</a></details></section><section class="v15-guide-card" id="guide-save"><h2>把资料整理成自己的研究</h2><p>收藏事件、资料或帖子时选择分类，也可以新建分类。进入“我的资料库”，为内容加标签、笔记或图片；勾选收藏后，AI可以一起整理要点、比较说法或回答问题。</p><p>使用“导出文字与图片”保存完整备份，之后可以导入并继续整理。</p><div class="v15-guide-bottom"><a class="v15-primary" href="#analysis">去持仓分析 ${icon('arrow')}</a><a class="v15-button" href="#news">去事件时间轴 ${icon('arrow')}</a><a class="v15-button" href="#library">去我的资料库 ${icon('arrow')}</a></div></section></div></div>`;}
